WITH with_windows AS (SELECT id, region, SUM(sqft) OVER w_running AS running_sum_sqft, AVG(sqft) OVER w_running AS running_avg_sqft, MAX(sqft) OVER w_running AS running_max_sqft FROM stores WINDOW w_running AS (PARTITION BY city ORDER BY sqft, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT id, region, running_sum_sqft, running_avg_sqft, running_max_sqft FROM with_windows ORDER BY running_sum_sqft DESC NULLS LAST;
